export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [state, setState] = useState<AuthState>({
    isLoading: true,
    isAuthenticated: false,
    hasClaudeToken: false,
    hasClaudeCreds: false,
    hasGitHubToken: false,
  });

  const refreshAuth = useCallback(async () => {
    const tokens = await loadAllTokens();
    setState({
      isLoading: false,
      isAuthenticated: !!tokens.spritesToken,
      hasClaudeToken: !!tokens.claudeToken,
      hasClaudeCreds: !!tokens.claudeCreds,
      hasGitHubToken: !!tokens.githubToken,
    });
  }, []);

  useEffect(() => {
    refreshAuth();
  }, [refreshAuth]);

  const saveSpritesToken = useCallback(async (token: string) => {
    await saveToken('spritesToken', token);
    await refreshAuth();
  }, [refreshAuth]);

  const saveClaudeTokenFn = useCallback(async (token: string) => {
    await saveToken('claudeToken', token);
    await refreshAuth();
  }, [refreshAuth]);

  const saveClaudeCreds = useCallback(async (creds: string) => {
    await saveToken('claudeCreds', creds);
    await refreshAuth();
  }, [refreshAuth]);

  const saveGitHubToken = useCallback(async (token: string) => {
    await saveToken('githubToken', token);
    await refreshAuth();
  }, [refreshAuth]);

  const signOut = useCallback(async () => {
    await clearAllTokens();
    await refreshAuth();
  }, [refreshAuth]);

  const getClaudeToken = useCallback(async () => {
    return loadToken('claudeToken');
  }, []);

  return (
    <AuthContext.Provider
      value={{
        ...state,
        refreshAuth,
        saveSpritesToken,
        saveClaudeToken: saveClaudeTokenFn,
        saveClaudeCreds,
        saveGitHubToken,
        signOut,
        getClaudeToken,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}
import { Platform } from 'react-native';
import * as SecureStore from 'expo-secure-store';

const KEYS = {
  spritesToken: 'sprites_api_token',
  claudeToken: 'claude_oauth_token',
  claudeCreds: 'claude_credentials_json',
  githubToken: 'github_token',
  assemblyAiToken: 'assemblyai_api_key',
  openAiToken: 'openai_api_key',
} as const;

export type TokenKey = keyof typeof KEYS;

export async function saveToken(key: TokenKey, value: string): Promise<void> {
  if (Platform.OS === 'web') {
    localStorage.setItem(KEYS[key], value);
  } else {
    await SecureStore.setItemAsync(KEYS[key], value);
  }
}

export async function loadToken(key: TokenKey): Promise<string | null> {
  if (Platform.OS === 'web') {
    return localStorage.getItem(KEYS[key]);
  }
  return SecureStore.getItemAsync(KEYS[key]);
}

export async function deleteToken(key: TokenKey): Promise<void> {
  if (Platform.OS === 'web') {
    localStorage.removeItem(KEYS[key]);
  } else {
    await SecureStore.deleteItemAsync(KEYS[key]);
  }
}

export async function hasToken(key: TokenKey): Promise<boolean> {
  const val = await loadToken(key);
  return val !== null && val.length > 0;
}

export async function loadAllTokens() {
  const [spritesToken, claudeToken, claudeCreds, githubToken, assemblyAiToken, openAiToken] = await Promise.all([
    loadToken('spritesToken'),
    loadToken('claudeToken'),
    loadToken('claudeCreds'),
    loadToken('githubToken'),
    loadToken('assemblyAiToken'),
    loadToken('openAiToken'),
  ]);
  return { spritesToken, claudeToken, claudeCreds, githubToken, assemblyAiToken, openAiToken };
}

export async function clearAllTokens(): Promise<void> {
  await Promise.all([
    deleteToken('spritesToken'),
    deleteToken('claudeToken'),
    deleteToken('claudeCreds'),
    deleteToken('githubToken'),
    deleteToken('assemblyAiToken'),
    deleteToken('openAiToken'),
  ]);
}

